import{_ as e,o as a,c as r,a3 as o}from"./chunks/framework.BLaSdaBb.js";const g=JSON.parse('{"title":"Quick Reference & Glossary","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-reference.md","filePath":"guide/quick-reference.md"}'),i={name:"guide/quick-reference.md"};function d(l,t,s,n,h,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="quick-reference-glossary" tabindex="-1">Quick Reference &amp; Glossary <a class="header-anchor" href="#quick-reference-glossary" aria-label="Permalink to &quot;Quick Reference &amp; Glossary&quot;">​</a></h1><h2 id="game-symbols-abbreviations" tabindex="-1">Game Symbols &amp; Abbreviations <a class="header-anchor" href="#game-symbols-abbreviations" aria-label="Permalink to &quot;Game Symbols &amp; Abbreviations&quot;">​</a></h2><h3 id="resources" tabindex="-1">Resources <a class="header-anchor" href="#resources" aria-label="Permalink to &quot;Resources&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symbol</th><th>Name</th><th>What it&#39;s for</th></tr></thead><tbody><tr><td>🪙</td><td>Gold</td><td>Hiring mercenaries, upgrades, training, city projects</td></tr><tr><td>🍞</td><td>Bread/Food</td><td>Recruiting followers (40 per recruit)</td></tr><tr><td>⚗️</td><td>Elixir</td><td>Recruitment (20 per recruit) and training costs</td></tr><tr><td>💎</td><td>Reagents</td><td>Researching skills (costs vary by tier)</td></tr><tr><td>👥</td><td>Followers</td><td>Population units that work city jobs or become soldiers</td></tr></tbody></table><h3 id="hero-unit-stats" tabindex="-1">Hero &amp; Unit Stats <a class="header-anchor" href="#hero-unit-stats" aria-label="Permalink to &quot;Hero &amp; Unit Stats&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Symbol</th><th>Name</th><th>What it means</th></tr></thead><tbody><tr><td>✨</td><td>Essence</td><td>Fuel for every hero ability. Runs out faster than health, recovers slowly</td></tr><tr><td>⚔</td><td>Attack</td><td>How hard your melee strikes land</td></tr><tr><td>🏹</td><td>Ranged</td><td>How hard bows and projectiles hit</td></tr><tr><td>⚗</td><td>Craft</td><td>Magical damage from arts (Transmute Blast, Vitriol Flask, etc.)</td></tr><tr><td>🛡</td><td>Defense</td><td>How much damage you block</td></tr><tr><td>👟</td><td>Speed</td><td>How fast you move and when you act in turn order</td></tr></tbody></table><h3 id="on-map-unit-badges" tabindex="-1">On-Map Unit Badges <a class="header-anchor" href="#on-map-unit-badges" aria-label="Permalink to &quot;On-Map Unit Badges&quot;">​</a></h3><p>These appear on soldier cards when selected:</p><table tabindex="0"><thead><tr><th>Icon</th><th>Meaning</th><th>What to do</th></tr></thead><tbody><tr><td>💰</td><td>Mercenary</td><td>Costs gold daily, walks away if unpaid even once</td></tr><tr><td>⚒</td><td>Drilling</td><td>Currently training at a barracks/hall</td></tr><tr><td>✋</td><td>Wage withheld</td><td>Intentionally unpaid (3-day grace before they leave)</td></tr><tr><td>🎖</td><td>Ready for promotion</td><td>Level 3+, gold, and right building; promote to Champion</td></tr><tr><td>🚩</td><td>Marching</td><td>On the road to you; shows arrival day</td></tr></tbody></table><h3 id="other-icons-in-battle-ui" tabindex="-1">Other Icons in Battle &amp; UI <a class="header-anchor" href="#other-icons-in-battle-ui" aria-label="Permalink to &quot;Other Icons in Battle &amp; UI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Icon</th><th>Meaning</th></tr></thead><tbody><tr><td>🧷</td><td>Mend the Column (heal all allies)</td></tr><tr><td>🪨</td><td>Immovable Object (place boulder on map)</td></tr><tr><td>💥</td><td>Unstoppable Force (shove enemy or burst with force)</td></tr><tr><td>🔁</td><td>Lookout (swap places with an ally)</td></tr><tr><td>🫳</td><td>Steal (take an item from a foe in reach)</td></tr></tbody></table><h2 id="terminology" tabindex="-1">Terminology <a class="header-anchor" href="#terminology" aria-label="Permalink to &quot;Terminology&quot;">​</a></h2><p><strong>Unit</strong> <em>(umbrella term)</em>: any character on the battlefield</p><ul><li><strong>Soldier</strong>: regular combat unit under a hero&#39;s command (warrior, rogue, or alchemist)</li><li><strong>Hero</strong>: leadership unit that can lead a party (Lord, Champion, Beastmaster)</li><li><strong>Creature</strong>: tamed beasts (Chimera, Salamander, Basilisk, Quicksilver Elemental, Brass Golem)</li><li><strong>Homunculus</strong>: wild creature spawns; cannot be tamed</li></ul><p><strong>Art / Skill / Working</strong> <em>(all the same thing)</em>: any ability a hero learns and uses</p><ul><li><strong>Passive</strong>: always on (Rally, Shield Wall, Beast Bond)</li><li><strong>Active</strong>: used on the battlefield, costs an action (Transmute Blast, Ensnare, Shadow Step)</li><li><strong>Map ability</strong>: used between fights, once per day (Mend the Column, Set Trap)</li></ul><p><strong>Building / Holding</strong> <em>(same thing)</em>: any structure on the map</p><ul><li><strong>City</strong>: large settlement you control; builds new structures, researches skills</li><li><strong>Grand Athanor</strong>: massive city at the world&#39;s heart; capturing it wins the game</li><li><strong>Farmstead</strong>: field that produces food</li><li><strong>Lair</strong>: home to a creature; capture it to hire that beast</li></ul><p><strong>Movement</strong></p><ul><li><strong>Move</strong>: an on-battlefield step to an adjacent tile (tactical)</li><li><strong>March</strong>: travel across the world map; a party marches from tile to tile across several days</li></ul><p><strong>Guild Resources</strong>: what your treasury holds</p><ul><li>It is <strong>gold</strong> or 🪙, never &quot;coin&quot;</li><li><strong>Stores</strong>: the pooled food, elixir, and reagents your guild holds</li></ul><hr><h2 id="quick-learner-s-path" tabindex="-1">Quick Learner&#39;s Path <a class="header-anchor" href="#quick-learner-s-path" aria-label="Permalink to &quot;Quick Learner&#39;s Path&quot;">​</a></h2><p><strong>First Campaign (25 min to first victory):</strong></p><ol><li><strong>Pick your Lord</strong>: Warrior (tanks), Rogue (speed), or Alchemist (magic)</li><li><strong>Pick your guild</strong>: choose one for the home terrain and perk you like</li><li><strong>First goal:</strong> Liberate your Grand Athanor nearby (the tutorial shows you how)</li><li><strong>Core loop each day:</strong><ul><li>Move your parties to attack or defend</li><li>End day → pay your army → repeat</li></ul></li><li><strong>Long goal:</strong> Capture Entropy&#39;s Grand Athanor at the world&#39;s center to win</li></ol><p><strong>Expand safely:</strong></p><ul><li>Capture buildings near your cities (they ward the blight)</li><li>Build farmsteads for food so you can recruit</li><li>Research your Lord&#39;s first art at the Town Hall</li><li>Don&#39;t venture deep into the blight until you have a strong army</li></ul><hr><h2 id="stat-quick-reference" tabindex="-1">Stat Quick Reference <a class="header-anchor" href="#stat-quick-reference" aria-label="Permalink to &quot;Stat Quick Reference&quot;">​</a></h2><h3 id="how-stats-grow" tabindex="-1">How Stats Grow <a class="header-anchor" href="#how-stats-grow" aria-label="Permalink to &quot;How Stats Grow&quot;">​</a></h3><ul><li><strong>Leveling in battle</strong>: gain XP for damage dealt and kills (free, risky)</li><li><strong>Paid training</strong>: spend gold at a barracks/hall; only charges for remaining XP</li></ul><h3 id="what-each-calling-excels-at" tabindex="-1">What Each Calling Excels At <a class="header-anchor" href="#what-each-calling-excels-at" aria-label="Permalink to &quot;What Each Calling Excels At&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Calling</th><th>Strength</th><th>Weakness</th></tr></thead><tbody><tr><td><strong>Warrior</strong></td><td>High defense, Rally makes whole party stronger</td><td>No magic, slower</td></tr><tr><td><strong>Rogue</strong></td><td>Fastest, ambush bonus, sneaks past dungeon floors</td><td>Fragile, lower damage per hit</td></tr><tr><td><strong>Alchemist</strong></td><td>Transmute Blast opens fights with raw damage, Essence-based arts</td><td>Frail, high upkeep</td></tr></tbody></table><h3 id="combat-modifier-quick-list" tabindex="-1">Combat Modifier Quick List <a class="header-anchor" href="#combat-modifier-quick-list" aria-label="Permalink to &quot;Combat Modifier Quick List&quot;">​</a></h3><p>What <strong>adds</strong> damage:</p><ul><li>Higher ground: +10% per height level (max +30%)</li><li>Flanking enemy: +25%</li><li>Behind enemy: +50%</li><li>Charging 2+ tiles: bonus damage</li><li>Rally active: +2 attack</li></ul><p>What <strong>reduces</strong> damage:</p><ul><li>Cover in forest/swamp: enemy harder to hit</li><li>Enemy at higher ground: −10% per height</li><li>Morale 0: −2 attack (after ally dies)</li><li>Shield Wall active: +3 defense</li></ul><hr><h2 id="where-to-find-things" tabindex="-1">Where to Find Things <a class="header-anchor" href="#where-to-find-things" aria-label="Permalink to &quot;Where to Find Things&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Question</th><th>Answer</th><th>Page</th></tr></thead><tbody><tr><td>How do I get started?</td><td>Tutorial walks you through first turn</td><td><a href="/getting-started.html">Getting Started</a></td></tr><tr><td>How do battles work?</td><td>Turn-by-turn tactics on a grid</td><td><a href="/guide/combat.html">Battles &amp; Dungeons</a></td></tr><tr><td>How do I recruit soldiers?</td><td>Followers + resources at a barracks/hall</td><td><a href="/guide/heroes.html">Heroes &amp; Parties</a></td></tr><tr><td>How do I research skills?</td><td>Town Hall in any city</td><td><a href="/guide/skills.html">Skills &amp; Research</a></td></tr><tr><td>What items should I equip?</td><td>Depends on your hero&#39;s class</td><td><a href="/guide/artifacts.html">Arms &amp; Artifacts</a></td></tr><tr><td>How do cities produce resources?</td><td>Assign Followers to jobs</td><td><a href="/guide/cities.html">Cities &amp; Holdings</a></td></tr><tr><td>How do I win?</td><td>Capture Entropy&#39;s Grand Athanor</td><td><a href="/guide/world.html">The World Map</a></td></tr><tr><td>Can I save on my phone and play on my laptop?</td><td>Yes, sign in with Google</td><td><a href="/guide/saving.html">Saving Your Campaign</a></td></tr><tr><td>How do I befriend other guilds?</td><td>Gift gold or trade with them</td><td><a href="/guide/diplomacy.html">Diplomacy &amp; Trade</a></td></tr><tr><td>What are those creatures in the wild?</td><td>Alchemical beasts you can tame</td><td><a href="/guide/bestiary.html">The Bestiary</a></td></tr></tbody></table>',42)])])}const m=e(i,[["render",d]]);export{g as __pageData,m as default};
